// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        amount = bound(amount, 1 wei, 1 ether * 1000);

        vm.deal(address(this), amount * 2);
        uint256 preDepositBal = address(this).balance;

        (bool okDeposit, ) = address(c).call{value: amount}("");
        assertTrue(okDeposit);
        uint256 balBeforeWithdraw = address(this).balance;

        c.withdrawAll();

        // Rule: withdrawAll pays the owner exactly the contract's full balance,
        // so the owner's balance grows by the deposited amount.
        assertTrue(address(this).balance == balBeforeWithdraw + amount);
    }
}
